19: /// A request for operations from a source's log.
20: pub enum Request<F: Family> {
21:     /// Fetch the operations in `[start, start + max_ops)`.
22:     Operations {
23:         /// Prove against the root the database had at this size.
24:         size: Location<F>,
25:         /// First operation to return.
26:         start: Location<F>,
27:         /// Maximum number of operations to return.
28:         max_ops: NonZeroU64,
29:     },
30:     /// Fetch the single operation at `start` plus the pinned nodes at `start`, the lowest
31:     /// location the client will retain. The proof in the response authenticates the pinned nodes,
32:     /// so there is no way to request them on their own.
33:     Boundary {
34:         /// Prove against the root the database had at this size.
35:         size: Location<F>,
36:         /// The operation to return, which is also the location of the returned pinned nodes.
37:         start: Location<F>,
38:     },
39: }
40: 
41: impl<F: Family> Request<F> {
42:     /// The size whose root the response's proof must verify against.
43:     pub const fn size(&self) -> Location<F> {
44:         match self {
45:             Self::Operations { size, .. } | Self::Boundary { size, .. } => *size,
46:         }
47:     }
48: 
49:     /// First operation to return.
50:     pub const fn start(&self) -> Location<F> {
51:         match self {
52:             Self::Operations { start, .. } | Self::Boundary { start, .. } => *start,
53:         }
54:     }
55: 
56:     /// Maximum number of operations to return.
57:     pub const fn max_ops(&self) -> NonZeroU64 {
58:         match self {
59:             Self::Operations { max_ops, .. } => *max_ops,
60:             Self::Boundary { .. } => NonZeroU64::MIN,
61:         }
62:     }
63: 
64:     /// Total-order key for map lookups. The final component separates the variants.
65:     fn order_key(&self) -> (u64, u64, u64, bool) {
66:         (
67:             *self.size(),
68:             *self.start(),
69:             self.max_ops().get(),
70:             matches!(self, Self::Boundary { .. }),
71:         )
72:     }
73: }
