223: /// One authenticated response, shaped like the [`Request`] it answers.
224: ///
225: /// In a [`Response::Boundary`], the proof, the operation, and the pinned nodes are verified as a
226: /// unit. The pinned nodes are only believable because the proof folds them into digests it already
227: /// commits to.
228: pub enum Response<F: Family, Op, D: Digest> {
229:     /// Answer to a [`Request::Operations`].
230:     Operations {
231:         /// Proof authenticating `operations` against the root at the requested size.
232:         proof: Proof<F, D>,
233:         /// The operations that were fetched.
234:         operations: Vec<Op>,
235:     },
236:     /// Answer to a [`Request::Boundary`].
237:     Boundary {
238:         /// Proof authenticating `op` against the root at the requested size.
239:         proof: Proof<F, D>,
240:         /// The operation at the requested boundary.
241:         op: Op,
242:         /// Pinned nodes at the requested location.
243:         pinned_nodes: Vec<D>,
244:     },
245: }
